"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[6332],{81126:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[{"name":"Stats","desc":"The values surfaced on leaderstats and the HUD. The round stats are\\noptional: `stats` is nested, so the shallow reconcile never adds them to\\na profile saved without them.","fields":[{"name":"coins","lua_type":"number","desc":"Soft currency balance"},{"name":"xp","lua_type":"number","desc":"Lifetime XP; level is derived from it"},{"name":"level","lua_type":"number","desc":"Cached level, kept in step with `xp` via the Level module"},{"name":"wins","lua_type":"number?","desc":"Rounds won"},{"name":"kills","lua_type":"number?","desc":"Kills across rounds"},{"name":"points","lua_type":"number?","desc":"Round score across rounds"}],"source":{"line":45,"path":"src/Shared/Types/ProfileTypes.luau"}},{"name":"ProfileData","desc":"The persisted document.\\n\\n`purchases`, `proccessed_passes` and `claims` are receipt ledgers keyed by id.\\nThey exist so a retried or replayed grant can be recognised and skipped \u2014 check\\nthe ledger before awarding, and write to it after.\\n\\nThe `ftue.version` field lets the onboarding flow be re-run for players who\\ncompleted an older version of it.","fields":[{"name":"userLevel","lua_type":"number","desc":"Permission tier for admin/moderation checks"},{"name":"inventory","lua_type":"Types.Inventory","desc":"All item records the player owns"},{"name":"inventory_equipped","lua_type":"{ string }","desc":"Record ids currently equipped"},{"name":"unlocks","lua_type":"{ [string]: number }","desc":"`[itemId] = unlockedAt`, reserved for gamepass-style entitlements"},{"name":"box_pity","lua_type":"{ [string]: number }","desc":"`[boxId] = opens since the last Legendary+ pull`, see BoxService"},{"name":"stats","lua_type":"Stats","desc":"Coins, XP and level"},{"name":"playerMarket","lua_type":"PlayerMarkets.PlayerMarketData","desc":"Player-run market state"},{"name":"settings","lua_type":"{}","desc":"Reserved for per-player settings"},{"name":"base","lua_type":"BaseUtil.BaseData","desc":"The player\'s base layout and props"},{"name":"basesLiked","lua_type":"{ [Types.Id]: Types.Timestamp }","desc":"Bases this player has liked, and when"},{"name":"ftue","lua_type":"{ completed: boolean, checkpoint: number, version: number }","desc":"First-time user experience progress"},{"name":"daily_rewards","lua_type":"DailyRewards.DailyRewardsData","desc":"Streak and last claim time"},{"name":"distanceDriven","lua_type":"number","desc":"Cumulative vehicle distance"},{"name":"total_time","lua_type":"number?","desc":"Analytics: seconds played"},{"name":"rounds_played","lua_type":"number?","desc":"Analytics: rounds completed"},{"name":"hasQueued","lua_type":"boolean?","desc":"Set forever on the first successful queue entry; gates first-queue guidance"},{"name":"purchases","lua_type":"{ [Types.RecordId]: Types.Timestamp }","desc":"`[purchaseId] = purchasedAt`"},{"name":"proccessed_passes","lua_type":"{ [Types.RecordId]: Types.Timestamp }","desc":"`[passId] = purchasedAt`"},{"name":"claims","lua_type":"{ [Types.RecordId]: Types.Timestamp }","desc":"`[ugcId] = claimedAt`"},{"name":"unsaved","lua_type":"{ [string]: number }","desc":"Scratch values deliberately excluded from persistence"}],"source":{"line":87,"path":"src/Shared/Types/ProfileTypes.luau"}},{"name":"Profile","desc":"A live ProfileDB session handle with this game\'s [ProfileData] on it. Everything\\nelse \u2014 session locking, saving, release \u2014 comes from ProfileDB.","fields":[{"name":"data","lua_type":"ProfileData","desc":"The persisted document"}],"source":{"line":170,"path":"src/Shared/Types/ProfileTypes.luau"}}],"name":"ProfileTypes","desc":"Shape of a player\'s saved profile \u2014 everything that persists between sessions.\\n\\n[ProfileData] is the document written to the datastore by ProfileDB. Because it is\\npersisted, every field has to survive players who saved under an older schema:\\noptional fields are optional because old profiles lack them, and code reading this\\ndata should default rather than assume.\\n\\nFeature subsystems own their own slices and re-export the shapes for them \u2014\\n`base` comes from `BaseUtil`, `daily_rewards` from [DailyRewards],\\n`playerMarket` from `PlayerMarkets`. This file stitches those together into the\\none document.\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/survival-islands - proprietary and confidential.","source":{"line":19,"path":"src/Shared/Types/ProfileTypes.luau"}}')}}]);